import re
from taf.rfrl.bts.devices.generic_bts import GenericBts, login_logout


class RDParametersGetter(GenericBts):

    def __init__(self):
        super(RDParametersGetter, self).__init__(bts_type="GNB")

    @staticmethod
    def get_value_for_specific_key(data, search_key):
        def find_value_for_specific_key(data, search_key):
            if isinstance(data, dict):
                if search_key in data:
                    return data[search_key]
                for key in data:
                    result = find_value_for_specific_key(data[key], search_key)
                    if result is not None:
                        return result
            elif isinstance(data, list):
                for item in data:
                    result = find_value_for_specific_key(item, search_key)
                    if result is not None:
                        return result
            return None

        return find_value_for_specific_key(data, search_key)

    @login_logout
    def get_dist_names_references(self, bts_id=0, du_id=0, reference_class_names=None):
        """
        Gets all managed objects from reference class names and creates dictionaries from distName to reference
        and from reference to distName

        e.g. output:
        ref_to_dist_name:
        {'/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-78301/LNCEL_R-1':
        ['/MRBTS-1/RAT-1/LTS-1/LNBTS_L-1/LNCEL_L-1', '/MRBTS-1/RAT-1/MCTRL-1/BBTOP_M-1/MRBTS_M-1/LNBTS_M-1/CELL_M-1',
        '/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-1/SCF-1/MRBTS_A-78301/LNBTS_A-78301/LNCEL_A-1']}
        dist_name_to_ref:
        {'/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-1/SCF-1/MRBTS_A-78301/LNBTS_A-78301/LNCEL_A-1':
        ['/MRBTS-1/RAT-1/MCTRL-1/BBTOP_M-1/MRBTS_M-1/LNBTS_M-1/CELL_M-1/LNCEL_M-1',
        '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-78301/LNCEL_R-1']}
        """

        reference_class_names = ["REF", "CONF_REF"] if reference_class_names is None else reference_class_names
        ref_to_dist_name = {}
        dist_name_to_ref = {}
        for refernce_class_name in reference_class_names:
            references = self.admin.get_managed_objects(class_name=refernce_class_name, timeout=10,
                                                        connection=self.rest_alias.format(bts_id, du_id))

            for refernce in references:
                ref_dist_name = refernce["distName"].split("/" + refernce_class_name)[0]
                dist_name = refernce["parameters"]["distName"]

                try:
                    ref_to_dist_name[ref_dist_name].append(dist_name)
                except KeyError:
                    ref_to_dist_name[ref_dist_name] = [dist_name]

                try:
                    dist_name_to_ref[dist_name].append(ref_dist_name)
                except KeyError:
                    dist_name_to_ref[dist_name] = [ref_dist_name]

        return ref_to_dist_name, dist_name_to_ref

    @login_logout
    def get_managed_objects_ids_from_refernces(self, managed_objects, bts_id=0, du_id=0, id_regex=r"_A-(\d+)",
                                               timeout=10, reference_class_names=None, id_reference_params=None):
        r"""
        Returns a dictionary with managed object dist names as keys and a dictionary as value where the ID found from
        id_regex and object parameters are stored. The ID is found from the dist name or from reference dist names.

        e.g. output:
        managed_objects: ["ASIRMOD_A", "RMOD_L", "ASIRMOD_R"] and id_regex: r"_A-(\d+)"
        {
            "/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-1/SCF-1/MRBTS_A-78301/EQM_A-1/APEQM_A-1/ASIRMOD_A-4": {id: 4, params: {...}},
            "/MRBTS-1/RAT-1/BTS_L-1/EQM_L-1/RMOD_L-10": {'id': 4, 'params': {...}},
            "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/ASIRMOD_R-7": {'id': 4, 'params': {...}}
        }
        """
        id_reference_params = ["configDN", "serialNumber"] if id_reference_params is None else id_reference_params
        ref_to_dist_name, dist_name_to_ref = self.get_dist_names_references(bts_id=bts_id, du_id=du_id,
                                                                            reference_class_names=reference_class_names)
        found_references_dict = {}
        for managed_object in managed_objects:
            managed_objects_info = self.admin.get_managed_objects(class_name=managed_object, timeout=timeout,
                                                                  connection=self.rest_alias.format(bts_id, du_id))
            if not managed_objects_info:
                continue
            for managed_object_info in managed_objects_info:
                dist_name = managed_object_info["distName"]
                ref_dist_names = dist_name_to_ref.get(dist_name, [])
                dist_names_ref = ref_to_dist_name.get(dist_name, [])
                object_references = ref_dist_names + dist_names_ref
                for reference_param in id_reference_params:  # trying to get additional referennces from parameters
                    value = self.get_value_for_specific_key(managed_object_info["parameters"], reference_param)
                    object_references.append(value) if value is not None else None

                object_id = None
                dist_name_object_id = re.search(id_regex, dist_name.split("/")[-1])
                if dist_name in found_references_dict and found_references_dict[dist_name]["id"] is not None:
                    object_id = found_references_dict[dist_name]["id"]
                elif dist_name_object_id is not None:
                    object_id = dist_name_object_id.group(1)
                    object_id = int(object_id) if object_id.isdigit() else object_id
                else:
                    for ref_dist_name in object_references:  # If object id is not found, trying to find in object references
                        dist_name_object_id = re.search(id_regex, ref_dist_name.split("/")[-1])
                        if dist_name_object_id is None:
                            continue
                        object_id = dist_name_object_id.group(1)
                        object_id = int(object_id) if object_id.isdigit() else object_id
                        break

                try:  # adding managed object dist name to found references dict
                    found_references_dict[dist_name]["id"] = object_id
                    found_references_dict[dist_name]["params"] = managed_object_info["parameters"]
                except KeyError:
                    found_references_dict[dist_name] = {"id": object_id, "params": managed_object_info["parameters"]}
                if object_id is None:
                    continue

                for ref_dist_name in object_references:  # If object id is found, creating references for it
                    try:
                        found_references_dict[ref_dist_name]["id"] = object_id
                    except KeyError:
                        found_references_dict[ref_dist_name] = {"id": object_id}
        return found_references_dict

    @login_logout
    def combine_managed_objects_info(self, managed_objects, bts_id=0, du_id=0, id_regex=r"_A-(\d+)",
                                     reference_class_names=None, id_reference_params=None, timeout=10):
        r"""
        Combine the given managed objects' dist names and parameters aggregated by the ID found using id_regex.
        :param managed_objects: list of managed objects to get information from
        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param str id_regex: regex to find the ID from distName, id need to be in the first group of the regex,
                             e.g. r"_A-(\d+)" or for ASIRMOD serialNumber r"(NH.*)"
        :param reference_class_names: List of reference class names to get references from, default ["REF", "CONF_REF"]
        :param id_reference_params: List of parameters to get additional references from, default ["configDN", "serialNumber"]
        :return: Dictionary with object IDs as keys and dictionaries with distNames and parameters as values

        e.g. output:
        managed_objects: ["ASIRMOD_A", "RMOD_L", "ASIRMOD_R"] and id_regex: r"_A-(\d+)"
        {
            4: {
                'distNames': ['/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-1/SCF-1/MRBTS_A-78301/EQM_A-1/APEQM_A-1/ASIRMOD_A-4',
                '/MRBTS-1/RAT-1/BTS_L-1/EQM_L-1/RMOD_L-10',
                '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/ASIRMOD_R-7', 'NH190500007'],
                "parameters": {...}
                }
        }
        """

        found_references_dict = self.get_managed_objects_ids_from_refernces(managed_objects, bts_id=bts_id, du_id=du_id,
                                                                            id_regex=id_regex, timeout=timeout,
                                                                            reference_class_names=reference_class_names,
                                                                            id_reference_params=id_reference_params)

        combined_info = {}
        for dist_name, managed_object_info in found_references_dict.items():
            object_id = managed_object_info["id"]
            if object_id is None:
                continue
            try:
                combined_info[object_id]["distNames"].append(dist_name)
                managed_object_params = managed_object_info.get("params", {})
                combined_info[object_id]["parameters"].update(managed_object_params)
            except KeyError:
                params = managed_object_info["params"] if "params" in managed_object_info else {}
                combined_info[object_id] = {"parameters": params, "distNames": [dist_name]}

        return combined_info
